tafsir_text:
{  قُلْ إِنِّيَ أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ }

المعنى :

{  قل إني أخاف إن عصيت ربي عذاب يوم عظيم } .  المعصية من النبي محال لمكان العصمة ولكن فرض المحال ليس بمحال .  .  والغرض تقرير أو تأكيد مبدأ المساواة بين الناس جميعا أمام الله وأنه خلق تعالى الجنة لمن أطاعه ولو كان عبدا حبشيا والنار لمن عصاه ولو كان سيدا قرشيا .  .  ويأتي الخوف من الله سبحانه على قدر العلم بعظمته :   " إنما يخشى الله من عباده العلماء-28 فاطر "  وبالأولى الأنبياء .

{  مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُ وَذَلِكَ الْفَوْزُ الْمُبِينُ }

المعنى :

{  من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين } كل من يخاف الهول الأكبر يرى النجاة منه رحمة كبرى وفوزا لا شيء أعظم منه .

{  بَلْ بَدَا لَهُم مَّا كَانُواْ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَاذِبُونَ }

المعنى :

{  بل بدا لهم ما كانوا يخفون من قبل } لا ينجو غدا من عذاب الله إلا من كان واضحا وصريحا في هذه الحياة تنسجم أقواله مع أفعاله ،  وهما معا انعكاس عن ذاته وواقعه ،  حتى كأن الجميع شيء واحد عند الله والناس أما الغامض المبهم الذي يعرف الخالق منه ما لا يعرفه المخلوق من الرياء والنفاق أما هذا فسوف يبدو له جزاء ريائه ونفاقه وتذهب نفسه حسرات على إساءته ويتمنى الخلاص بالرد إلى الدنيا ولكن هيهات .  {  ولو ردوا لعادوا لما نهوا عنه وإنهم لكاذبون } في قولهم :  يا ليتنا نرد ولا نكذب بآيات ربنا ونكون من المؤمنين .  .  ولقد قرأنا عن عشرات المجرمين أنهم تابوا وهم في غياهب السجن ،  حتى إذا خرجوا عادوا إلى إجرامهم وآثامهم {  وإذا مسكم الضر في البحر ضل من تدعون إلا إياه فلما نجاكم إلى البر أعرضتم وكان الإنسان كفورا- 66 الإسراء } .

{  وَمَا الْحَيَاةُ الدُّنْيَا إِلاَّ لَعِبٌ وَلَهْوٌ وَلَلدَّارُ الآخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلاَ تَعْقِلُونَ }

المعنى :

{  وما الحياة الدنيا إلا لعب ولهو } تقدم نظيره في الآية 185 من آل عمران ج2 ص224 .

{  قُل لَّوْ أَنَّ عِندِي مَا تَسْتَعْجِلُونَ بِهِ لَقُضِيَ الأَمْرُ بَيْنِي وَبَيْنَكُمْ وَاللّهُ أَعْلَمُ بِالظَّالِمِينَ }

المعنى :

{  قل لو أن عندي ما تستعجلون به } من العذاب {  لقضي الأمر بيني وبينكم } بإهلاك من ظلم منكم غضبا لله تعالى {  والله أعلم بالظالمين } يعجل أو يؤجل العذاب على ما تقتضيه حكمته .

{  قُلِ اللّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ }

المعنى :

{  قل الله ينجيكم منها ومن كل كرب } فكان عليكم أن تعظموا نعمة الله وتشكروها {  ثم أنتم تشركون } ولكنكم بعد أن أنعم عليكم بالنجاة بدلتم نعمة الله كفرا وشركا .

{  اتَّبِعْ مَا أُوحِيَ إِلَيْكَ مِن رَّبِّكَ لا إِلَهَ إِلاَّ هُوَ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ }

المعنى :

{  اتبع ما أوحي إليك من ربك لا إله إلا هو واعرض عن المشركين } .  هذا أمر من الله لنبيه الأكرم أن ينذر ويبشر بالقرآن ويداوم على ذلك ولا يبالي بجحود المشركين وتكذيبهم واستهزائهم .  .  وغريب قول من قال :  إن هذه الآية منسوخة بآية القتال ،  إن هذا القول غريب لأن الله سبحانه لم يأمر النبي صلى الله عليه وسلم بترك قتال المشركين في هذه الآية كي يقال :  إنها منسوخة بالآية الآمرة بقتالهم وإنما أمره بمتابعة الدعوة إلى الحق وعدم المبالاة بتكذيب المشركين .  .  وبديهة أن الأمر بمتابعة الدعوة مع عدم المبالاة شيء ،  والأمر بالقتال شيء آخر .  .  وأول شرط للنسخ أن يتحد الموضوع .

{  وَلَوْ شَاء اللّهُ مَا أَشْرَكُواْ وَمَا جَعَلْنَاكَ عَلَيْهِمْ حَفِيظًا وَمَا أَنتَ عَلَيْهِم بِوَكِيلٍ }

المعنى :

{  ولو شاء الله ما أشركوا } أي أنه تعالى لم يرد إلجاءهم إلى الإيمان ،  وقهرهم على ترك الشرك بكلمة {  كن فيكون } الذي خلق بها الكون ولو أراد إيمانهم بإرادته التكوينية هذه ما أشركوا .  أنظر تفسير الآية 26 من سورة البقرة فقرة  " التكوين والتشريع "  ج 1 ص 72 {  وما جعلناك عليهم حفيظا وما أنت عليهم بوكيل } الجملة الأولى والثانية بمعنى واحد ،  أو متقاربتان في المعنى ولا نفهم أي غرض من ذلك سوى التأكيد بل وهذا التأكيد تأكيد أيضا لقوله تعالى :  {  وأعرض عن المشركين } لأنه لو كان وكيلا وحفيظا عليهم لما جاز الإعراض عنهم :  {  إن إلينا إيابهم ثم إن علينا حسابهم- 25 الغاشية } .

{  وَذَرُواْ ظَاهِرَ الإِثْمِ وَبَاطِنَهُ إِنَّ الَّذِينَ يَكْسِبُونَ الإِثْمَ سَيُجْزَوْنَ بِمَا كَانُواْ يَقْتَرِفُونَ }

المعنى :

{  وذروا ظاهر الإثم وباطنه } المراد بالإثم فعل الحرام الموجب له وظاهره ارتكاب المعصية علانية وباطنه ارتكابها سرا وقد نهى سبحانه عن اقتراف جميع المعاصي ما ظهر منها وما بطن {  إن الذين يكسبون الإثم سيجزون بما كانوا يقترفون } من إتباع الأهواء بغير علم ولا يتركون سدى من غير حساب وعقاب .

{  وَكَذَلِكَ نُوَلِّي بَعْضَ الظَّالِمِينَ بَعْضًا بِمَا كَانُواْ يَكْسِبُونَ }

المعنى :

{  وكذلك نولي بعض الظالمين بعضا بما كانوا يكسبون } لما ذكر سبحانه في الآية المتقدمة 127 أنه هو ولي المؤمنين ذكر هنا أن الكافرين من الجن والإنس بعضهم أولياء بعض لأنهم شركاء في الكفر والظلم ويوم القيامة يكونون شركاء أيضا في العذاب والعقاب .

{  فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَاسِعَةٍ وَلاَ يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ }

المعنى :

{  فإن كذبوك فقل ربكم ذو رحمة واسعة ولا يرد بأسه عن القوم المجرمين } . أي إن كذبوك يا محمد فلا توئسهم من رحمة الله وقل لهم :  إن الله يقبلكم ويصفح عنكم إن تبتم وأنبتم كما أنه ينتقم منكم إذا أصررتم على ما أنتم عليه ، و في هذه الآية وعد و وعيد ، رضا الله و غضبه ، رضاه عمن التجأ إليه طالبا المغفرة ،  وغضبه على من أصر على التمرد والعناد :  {  لئن شكرتم لأزيدنكم ولئن كفرتك إن عذابي لشديد- 7 إبراهيم } .

{  لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَاْ أَوَّلُ الْمُسْلِمِينَ }

المعنى :

{  لا شريك له وبذلك أمرت وأنا أول المسلمين } هذه الآية توضيح وتأكيد لما تضمنته الآية السابقة من التوحيد والإخلاص .  .  ومحمد صلى الله عليه وسلم أول المسلمين من أمته بطبيعة الحال لأنه صاحب الدعوة .
